=<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Petición — Formulario JSON</title>
  <style>
    :root{
      --bg: #0b0f14;
      --card: rgba(21, 28, 38, 0.7);
      --stroke: rgba(255,255,255,0.08);
      --text: #e6ebf3;
      --muted: #aab6c5;
      --accent: #77eaff;
      --accent-2: #9b8cff;
      --danger: #ff6b6b;
      --success: #32d296;
      --radius: 18px;
      --shadow: 0 10px 35px rgba(0,0,0,0.45), inset 0 0 0 1px var(--stroke);
    }

    *{ box-sizing: border-box; }
    html,body{ height:100%; }
    body{
      margin:0;
      background:
        radial-gradient(1200px 600px at 10% -10%, rgba(119,234,255,0.12), transparent 60%),
        radial-gradient(1000px 500px at 110% 10%, rgba(155,140,255,0.10), transparent 60%),
        linear-gradient(180deg, #0a0e13 0%, #0b0f14 100%);
      color:var(--text);
      font: 16px/1.5 ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Inter, Arial, sans-serif;
      display:grid;
      place-items:center;
      padding:24px;
    }

    .wrap{
      width:100%;
      max-width: 720px;
    }

    header{
      margin-bottom: 22px;
      display:flex; align-items:center; gap:12px;
    }
    .logo{
      width:40px; height:40px; border-radius:12px;
      background:
        conic-gradient(from 210deg, var(--accent), var(--accent-2) 50%, var(--accent) 100%);
      filter: blur(.2px) saturate(120%);
      box-shadow: 0 0 0 2px rgba(255,255,255,0.06), 0 10px 30px rgba(119,234,255,0.14);
    }
    h1{
      font-size: clamp(18px, 3vw, 22px);
      margin:0;
      letter-spacing: .3px;
      font-weight: 650;
    }
    .subtitle{
      margin:2px 0 0 0;
      color:var(--muted);
      font-size: 14px;
    }

    .card{
      background: var(--card);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: blur(10px) saturate(130%);
      -webkit-backdrop-filter: blur(10px) saturate(130%);
      padding: 22px;
      border: 1px solid var(--stroke);
    }

    form{
      display:grid; gap:16px;
    }

    .field{
      display:grid; gap:8px;
    }
    label{
      font-size: 14px;
      color: var(--muted);
    }
    input[type="text"], textarea{
      width:100%;
      background: rgba(255,255,255,0.03);
      color:var(--text);
      border:1px solid var(--stroke);
      border-radius: 14px;
      padding: 12px 14px;
      outline: none;
      transition: border-color .2s, box-shadow .2s, transform .04s;
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.02);
    }
    textarea{ min-height: 140px; resize: vertical; }

    input:focus, textarea:focus{
      border-color: rgba(119,234,255,0.35);
      box-shadow: 0 0 0 4px rgba(119,234,255,0.14), inset 0 0 0 1px rgba(119,234,255,0.06);
    }

    .row{
      display:flex; gap:12px; flex-wrap:wrap;
    }

    .btn{
      appearance: none; -webkit-appearance: none;
      border: 0;
      border-radius: 14px;
      padding: 12px 16px;
      font-weight: 600;
      cursor: pointer;
      transition: transform .06s ease, box-shadow .2s ease, background .2s ease, opacity .2s ease;
      display:inline-flex; align-items:center; gap:10px;
      background: linear-gradient(135deg, rgba(119,234,255,0.18), rgba(155,140,255,0.18));
      color: var(--text);
      box-shadow: 0 8px 22px rgba(119,234,255,0.12), inset 0 0 0 1px rgba(255,255,255,0.06);
    }
    .btn:hover{ transform: translateY(-1px); }
    .btn:active{ transform: translateY(0); }
    .btn[disabled]{ opacity:.6; cursor:not-allowed; }

    .ghost{
      background: transparent;
      border: 1px dashed rgba(255,255,255,0.15);
      box-shadow: none;
    }

    .status{
      display:none;
      border-radius: 12px;
      padding: 10px 12px;
      font-size: 14px;
    }
    .status.ok{ display:flex; gap:8px; align-items:center; color:#0b291b; background: rgba(50,210,150,0.18); border:1px solid rgba(50,210,150,0.35); }
    .status.err{ display:flex; gap:8px; align-items:center; color:#2a0b0b; background: rgba(255,107,107,0.18); border:1px solid rgba(255,107,107,0.35); }

    .hint{
      color:var(--muted);
      font-size: 12.5px;
      margin-top:-2px;
    }

    footer{
      margin-top: 14px;
      color: var(--muted);
      font-size: 12.5px;
      display:flex; justify-content:space-between; gap:10px; flex-wrap:wrap;
    }

    .spinner{
      width:16px; height:16px; border-radius:50%;
      border:2px solid rgba(255,255,255,0.2);
      border-top-color: var(--accent);
      animation: spin 1s linear infinite;
    }
    @keyframes spin{ to{ transform: rotate(360deg); } }

    @media (prefers-color-scheme: light){
      :root{
        --bg: #f6f8fb;
        --card: rgba(255,255,255,0.8);
        --stroke: rgba(0,0,0,0.08);
        --text: #0f1722;
        --muted: #5a6677;
      }
      body{
        background:
          radial-gradient(1400px 700px at -10% -10%, rgba(119,234,255,0.2), transparent 60%),
          radial-gradient(1200px 600px at 110% 0%, rgba(155,140,255,0.2), transparent 60%),
          linear-gradient(180deg, #f2f5fa 0%, #f6f8fb 100%);
      }
    }
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="logo" aria-hidden="true"></div>
      <div>
        <h1>Enviar petición</h1>
        <p class="subtitle">Formulario minimalista que envía <strong>JSON por POST</strong> al backend.</p>
      </div>
    </header>

    <section class="card">
      <!-- Instrucciones rápidas:
           1) Completa Usuario y Mensaje.
           2) Clic en Enviar; revisa DevTools > Network para ver el POST JSON.
           3) URL destino: https://<N8N_INSTANCE>/webhook/<path>
           Estructura JSON:
             {
               "usuario": "string",
               "mensaje": "string",
               "timestamp": "ISO-8601"
             }
      -->
      <form id="peticionForm" novalidate>
        <div class="field">
          <label for="usuario">Usuario</label>
          <input id="usuario" name="usuario" type="text" inputmode="text" placeholder="Tu nombre o usuario"
                 minlength="2" maxlength="80" required autocomplete="name" />
          <div class="hint">Requerido. 2–80 caracteres.</div>
        </div>

        <div class="field">
          <label for="mensaje">Mensaje</label>
          <textarea id="mensaje" name="mensaje" placeholder="Escribe tu petición…" minlength="4" maxlength="2000" required></textarea>
          <div class="hint">Requerido. 4–2000 caracteres.</div>
        </div>

        <div class="row">
          <button id="submitBtn" type="submit" class="btn">
            <span class="spinner" style="display:none" aria-hidden="true"></span>
            <span id="btnText">Enviar</span>
          </button>
          <button type="reset" class="btn ghost">Limpiar</button>
        </div>

        <div id="ok" class="status ok" role="status" aria-live="polite" style="display:none;">
          ✅ <span>Enviado correctamente.</span>
        </div>
        <div id="err" class="status err" role="status" aria-live="polite" style="display:none;">
          ⚠️ <span>Ocurrió un problema al enviar. Intenta de nuevo.</span>
        </div>
      </form>

      <footer>
        <span>Futuro-ready UI ✦ glass minimal</span>
        <span>JSON • fetch • POST</span>
      </footer>
    </section>
  </div>

  <script>
    (function(){
      const form = document.getElementById('peticionForm');
      const usuario = document.getElementById('usuario');
      const mensaje = document.getElementById('mensaje');
      const btn = document.getElementById('submitBtn');
      const btnText = document.getElementById('btnText');
      const spin = btn.querySelector('.spinner');
      const ok = document.getElementById('ok');
      const err = document.getElementById('err');

      const ENDPOINT = "https://<N8N_INSTANCE>/webhook/<path>";

      function setBusy(b){
        btn.disabled = b;
        spin.style.display = b ? 'inline-block' : 'none';
        btnText.textContent = b ? 'Enviando…' : 'Enviar';
      }

      function show(el){
        el.style.display = 'flex';
      }
      function hide(el){
        el.style.display = 'none';
      }

      function validate(){
        // Simple front validation
        if (!usuario.value || usuario.value.trim().length < 2){
          usuario.focus();
          return false;
        }
        if (!mensaje.value || mensaje.value.trim().length < 4){
          mensaje.focus();
          return false;
        }
        return true;
      }

      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        hide(ok); hide(err);

        if (!validate()) return;

        const payload = {
          usuario: usuario.value.trim(),
          mensaje: mensaje.value.trim(),
          timestamp: new Date().toISOString()
        };

        try{
          setBusy(true);
          const res = await fetch(ENDPOINT, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify(payload),
            // credentials omitted intentionally; add 'credentials' if your backend needs cookies
          });

          if (!res.ok){
            // try to read error
            let info = '';
            try{ info = await res.text(); } catch(_){}
            console.error('Respuesta no OK:', res.status, info);
            show(err);
            return;
          }

          show(ok);
          form.reset();
        }catch(ex){
          console.error('Error de red:', ex);
          show(err);
        }finally{
          setBusy(false);
        }
      }, { passive:false });
    })();
  </script>
</body>
</html>
